// Selecciona el blog activo menos procesado recientemente (rotación automática)
const config = $('⚙️ CONFIG').first().json;
const allRows = $input.all().map(i => i.json);

// Filtrar solo blogs activos con BLOG_ID válido
const blogs = allRows.filter(b =>
  (b.ACTIVE === 'YES' || b.ACTIVE === 'yes') &&
  b.BLOG_ID &&
  b.BLOG_ID.length > 5 &&
  !b.BLOG_ID.startsWith('ASSET')
);

if (blogs.length === 0) {
  return [{ json: { _error: 'No hay blogs activos en la hoja con BLOG_ID válido.' } }];
}

// Ordenar por CLUSTERS_ULTIMO_PROCESO ascendente (nulls/vacíos = más antiguos = primero)
blogs.sort((a, b) => {
  const da = a.CLUSTERS_ULTIMO_PROCESO ? new Date(a.CLUSTERS_ULTIMO_PROCESO) : new Date(0);
  const db = b.CLUSTERS_ULTIMO_PROCESO ? new Date(b.CLUSTERS_ULTIMO_PROCESO) : new Date(0);
  return da - db;
});

const blog = blogs[0];

// Detectar ESTRATEGIA por palabras clave en NICHO o BLOG_NAME
const texto = ((blog.NICHO || '') + ' ' + (blog.BLOG_NAME || '')).toLowerCase();
const legalKW = ['abog', 'litig', 'legal', 'leyes', 'juicio', 'impuesto',
                  'multa', 'accidente', 'bienes ra', 'familia usa',
                  'notari', 'herencia', 'divorcio', 'demanda', 'delito'];
const isLegal = legalKW.some(kw => texto.includes(kw));

// Usar ESTRATEGIA de la hoja si está definida, si no auto-detectar
const estrategia = blog.ESTRATEGIA || (isLegal ? 'lead_abogados' : 'animales_productos');

// Definir funnel URL: usar LEAD_MAGNET_URL del blog si existe, si no el global
const funnelUrl = blog.LEAD_MAGNET_URL ||
  (isLegal ? config.FUNNEL_ABOGADOS : config.FUNNEL_ANIMALES);

const brandColor = isLegal ? config.BRAND_COLOR_ABOGADOS : config.BRAND_COLOR_ANIMALES;

return [{
  json: {
    // Datos del blog
    BLOG_ID:       blog.BLOG_ID,
    BLOG_NAME:     blog.BLOG_NAME,
    NICHO:         blog.NICHO,
    ESPECIE:       blog.ESPECIE || '',
    AMAZON_TAG:    blog.AMAZON_TAG || '',
    TELEGRAM_URL:  blog.TELEGRAM_URL || '',
    WHATSAPP_URL:  blog.WHATSAPP_URL || '',
    _rowNumber:    blog._rowNumber,
    // Estrategia detectada
    ESTRATEGIA:    estrategia,
    IS_LEGAL:      isLegal,
    FUNNEL_URL:    funnelUrl,
    BRAND_COLOR:   brandColor,
    BRAND_NAME:    blog.BLOG_NAME,
    // Config global
    DEEPSEEK_API_KEY:       config.DEEPSEEK_API_KEY,
    LABEL_PILAR:            config.LABEL_PILAR,
    MAX_CLUSTER_POR_GRUPO:  config.MAX_CLUSTER_POR_GRUPO,
    SHEET_ID:               config.SHEET_ID,
    HOJA_BLOGS:             config.HOJA_BLOGS
  }
}];

// Agrupa por cluster, samplea 1 pilar + MAX cluster posts,
// aplica Ley 2 (skip si ya tiene los 3 bloques)

const blogData = $('🎯 Seleccionar Blog (Rotación Autopilot)').first().json;
const LABEL_PILAR = blogData.LABEL_PILAR.toLowerCase().trim();
const MAX = blogData.MAX_CLUSTER_POR_GRUPO || 10;

const posts = $input.all().map(i => ({
  id:      i.json.id,
  title:   i.json.title,
  url:     i.json.url,
  labels:  (i.json.labels || []).map(l => l.toLowerCase().trim()),
  content: i.json.content || ''
}));

if (posts.length === 0) {
  return [{ json: { _error: `El blog ${blogData.BLOG_NAME} no tiene posts publicados.` } }];
}

// Agrupar por label temática (excluyendo la label pilar)
const grupos = {};
for (const post of posts) {
  const topicLabels = post.labels.filter(l => l !== LABEL_PILAR);
  if (topicLabels.length === 0) continue;
  const key = topicLabels[0];
  if (!grupos[key]) grupos[key] = { pilar: null, clusters: [] };
  if (post.labels.includes(LABEL_PILAR)) {
    grupos[key].pilar = post;
  } else {
    grupos[key].clusters.push(post);
  }
}

const resultado = [];

for (const [topico, grupo] of Object.entries(grupos)) {
  if (!grupo.pilar) continue;
  const pilar = grupo.pilar;

  // Shuffle y samplear clusters
  const shuffled = [...grupo.clusters].sort(() => Math.random() - 0.5).slice(0, MAX);

  const enriquecer = (post, isPilar) => {
    const hasCluster = post.content.includes('<!-- CLUSTER_BLOCK -->');
    const hasCTA     = post.content.includes('<!-- CTA_BLOCK -->');
    const hasPopup   = post.content.includes('<!-- POPUP_BLOCK -->');

    // ⚖️ LEY 2: skip si ya tiene los 3 bloques
    const yaCompleto = isPilar
      ? (hasCTA && hasPopup)
      : (hasCluster && hasCTA && hasPopup);

    return {
      id: post.id, title: post.title, url: post.url,
      labels: post.labels, content: post.content,
      isPilar, isCluster: !isPilar,
      pillarTitle: isPilar ? null : pilar.title,
      pillarUrl:   isPilar ? null : pilar.url,
      topico,
      needsCluster: !isPilar && !hasCluster,
      needsCTA:     !hasCTA,
      needsPopup:   !hasPopup,
      _skip:        yaCompleto,
      // Pasar contexto del blog
      BLOG_ID:          blogData.BLOG_ID,
      BLOG_NAME:        blogData.BLOG_NAME,
      ESPECIE:          blogData.ESPECIE,
      AMAZON_TAG:       blogData.AMAZON_TAG,
      ESTRATEGIA:       blogData.ESTRATEGIA,
      IS_LEGAL:         blogData.IS_LEGAL,
      FUNNEL_URL:       blogData.FUNNEL_URL,
      BRAND_COLOR:      blogData.BRAND_COLOR,
      DEEPSEEK_API_KEY: blogData.DEEPSEEK_API_KEY,
      _sheetRowNumber:  blogData._rowNumber,
      SHEET_ID:         blogData.SHEET_ID,
      HOJA_BLOGS:       blogData.HOJA_BLOGS
    };
  };

  resultado.push({ json: enriquecer(pilar, true) });
  for (const cp of shuffled) {
    resultado.push({ json: enriquecer(cp, false) });
  }
}

return resultado.length > 0
  ? resultado
  : [{ json: { _error: 'No se encontraron clusters con pilar definido.' } }];

// ⚖️ LEY 1: DeepSeek NO recibe el contenido del artículo.
// Solo recibe: título, tema, especie, datos del pilar, config de marca.
// Genera 3 bloques: clusterBlock, ctaBlock, popupContent

const p = $input.item.json;
const isLegal = p.IS_LEGAL || p.ESTRATEGIA === 'lead_abogados';
const labelsText = p.labels.filter(l => l !== 'pilar' && l !== 'pillar').join(', ') || p.topico || 'blog';
const especie = p.ESPECIE || labelsText;

const systemMsg =
`Eres un diseñador HTML/CSS experto en blogs hispanohablantes, marketing de conversión y captación de leads.

⚠️ REGLAS ABSOLUTAS — sin excepción:
1. NUNCA incluyas, reproduzcas ni hagas referencia al contenido del artículo. No lo tienes y no lo necesitas.
2. Responde ÚNICAMENTE con JSON válido. Sin markdown, sin texto extra.
3. CSS 100% inline (style="..."). Sin clases externas ni hojas de estilo.
4. Diseños mobile-first. Emojis ESPECÍFICOS del nicho/especie/tema, NUNCA ✅❌☑️.
5. El popup debe incluir el HTML + el script JS inline funcional.`;

// ===== PROMPTS POR ESTRATEGIA =====
let estrategiaInstr = '';

if (isLegal) {
  // --- ESTRATEGIA: LEAD_ABOGADOS ---
  estrategiaInstr = `
ESTRATEGIA: Captación de leads para abogados (USA, español)
NICHO LEGAL: ${labelsText}
URL del formulario lead: ${p.FUNNEL_URL}
Color de marca: ${p.BRAND_COLOR}
Blog: ${p.BLOG_NAME}

🔷 BLOQUE 1 — clusterBlock (si isCluster=true):
• Wrapper flex, background:#f0f4ff, border-left:5px solid ${p.BRAND_COLOR}
• Imagen 78×78px: gradient ${p.BRAND_COLOR}, emoji legal temático (⚖️ 🏛️ 📜 🔏 según el tema "${labelsText}")
• Texto: 2 líneas que conecten el tema del post con la guía completa del pilar legal
  Ej: para accidentes → "🚗⚖️ Este es un aspecto del proceso. La guía completa explica cada etapa..."
• Link: color ${p.BRAND_COLOR}, bold, "Ver guía completa: ${p.pillarTitle || ''} →" → ${p.pillarUrl || ''}
• Marcadores: <!-- CLUSTER_BLOCK --> ... <!-- /CLUSTER_BLOCK -->

🔶 BLOQUE 2 — ctaBlock:
• Cajón de captación de leads. Tono: urgente, confiable, profesional.
• Fondo gradient ${p.BRAND_COLOR} a versión oscura. Border-radius:14px. Padding:28px.
• Imagen 90×90px: gradient contrastante + emoji legal urgente del tema (🆘 ⚡ 🏛️)
• Título H2: "¿[situación legal del nicho]? Consulta GRATIS con un abogado"
  Ejemplo para accidentes: "¿Tuviste un accidente? Habla HOY con un abogado"
• 2 bullets: beneficios específicos (plazos, compensación, proceso)
  Usa emojis legales, NO genéricos
• Botón blanco, texto ${p.BRAND_COLOR}, bold: "Solicitar Consulta Gratuita →"
• href del botón: ${p.FUNNEL_URL}
• Marcadores: <!-- CTA_BLOCK --> ... <!-- /CTA_BLOCK -->

🟣 BLOQUE 3 — popupContent (objeto JSON, NO HTML aún):
Genera un objeto JSON con los datos del popup de urgencia legal:
{
  "title": "[titular urgente con emoji legal]",
  "description": "[1-2 oraciones de urgencia + beneficio clave]",
  "ctaText": "[texto del botón de acción]",
  "ctaUrl": "${p.FUNNEL_URL}",
  "bgColor": "${p.BRAND_COLOR}",
  "emoji": "[1 emoji legal urgente del tema]"
}`;
} else {
  // --- ESTRATEGIA: ANIMALES_PRODUCTOS ---
  estrategiaInstr = `
ESTRATEGIA: SEO clusters + venta de productos para mascotas/animales
ESPECIE/NICHO: ${especie} | ${labelsText}
URL del funnel/lead magnet: ${p.FUNNEL_URL}
Color de marca: ${p.BRAND_COLOR}
Blog: ${p.BLOG_NAME}
${p.AMAZON_TAG ? `Amazon tag: ${p.AMAZON_TAG}` : ''}

🔷 BLOQUE 1 — clusterBlock (si isCluster=true):
• Wrapper flex, background:#f0fff4, border-left:5px solid ${p.BRAND_COLOR}
• Imagen 78×78px: gradient ${p.BRAND_COLOR}, emoji ESPECÍFICO de la especie "${especie}" (no genérico)
• Texto: 2 líneas invitando a leer el pilar completo sobre "${especie}"
  Usa 2 emojis de la especie/nicho en el texto
• Link bold, color ${p.BRAND_COLOR}: "Ver guía completa: ${p.pillarTitle || ''} →" → ${p.pillarUrl || ''}
• Marcadores: <!-- CLUSTER_BLOCK --> ... <!-- /CLUSTER_BLOCK -->

🔶 BLOQUE 2 — ctaBlock:
• Cajón de conversión para dueños de ${especie}. Tono: amigable, apasionado.
• Fondo gradient ${p.BRAND_COLOR} a versión oscura. Border-radius:16px. Padding:30px.
• Imagen 90×90px: gradient contrastante + emoji GRANDE de la especie ${especie}
• Título: emoji de valor/sorpresa del nicho + gancho específico para dueños de ${especie}
• 2 bullets: beneficios concretos para ${especie} con emojis de la especie
• Botón blanco, texto ${p.BRAND_COLOR}, bold: acción concreta y específica para ${especie}
• href del botón: ${p.FUNNEL_URL}
• Marcadores: <!-- CTA_BLOCK --> ... <!-- /CTA_BLOCK -->

🟣 BLOQUE 3 — popupContent (objeto JSON, NO HTML aún):
Genera un objeto JSON con datos del popup para dueños de ${especie}:
{
  "title": "[titular con emoji de ${especie} + beneficio clave]",
  "description": "[1-2 oraciones de valor + urgencia emocional para el dueño]",
  "ctaText": "[texto del botón específico para ${especie}]",
  "ctaUrl": "${p.FUNNEL_URL}",
  "bgColor": "${p.BRAND_COLOR}",
  "emoji": "[1 emoji de la especie ${especie}]"
}`;
}

const userMsg =
`Genera 3 bloques para este post:

📝 Título: "${p.title}"
🏷️ Temas: ${labelsText}
${p.isCluster
  ? `📌 Tipo CLUSTER. Pilar: "${p.pillarTitle}" → ${p.pillarUrl}`
  : `🏆 Tipo PILAR (clusterBlock = "")`
}
${p.isCluster && p.needsCluster ? `⚡ Generar clusterBlock.` : `ℹ️ clusterBlock = "" (no requerido).`}
${p.needsCTA    ? `⚡ Generar ctaBlock.`    : `ℹ️ ctaBlock = "" (ya existe).`}
${p.needsPopup  ? `⚡ Generar popupContent.` : `ℹ️ popupContent = {} (ya existe).`}

${estrategiaInstr}

Responde SOLO este JSON:
{
  "clusterBlock": "...",
  "ctaBlock": "...",
  "popupContent": { "title": "...", "description": "...", "ctaText": "...", "ctaUrl": "...", "bgColor": "...", "emoji": "..." }
}`;

return {
  json: {
    ...p,
    _deepseekBody: JSON.stringify({
      model: 'deepseek-chat',
      messages: [
        { role: 'system', content: systemMsg },
        { role: 'user',   content: userMsg   }
      ],
      max_tokens: 3000,
      temperature: 0.75,
      response_format: { type: 'json_object' }
    })
  }
};

// ⚖️ LEY 1: Solo append en posiciones fijas. Nunca .replace() en el contenido original.
// Inserta: clusterBlock (65%), ctaBlock (final), popupBlock con JS inline (final)

const dsItem   = $input.item.json;
const postData = $('🧠 Prompt Multi-Estrategia (DeepSeek)').item.json;

// --- Parsear respuesta de DeepSeek ---
let raw = '';
try { raw = dsItem.choices[0].message.content || ''; } catch(e) { raw = ''; }

const cleaned = raw.replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();

let clusterBlock  = '';
let ctaBlock      = '';
let popupData     = null;

try {
  const parsed    = JSON.parse(cleaned);
  clusterBlock    = (parsed.clusterBlock  || '').trim();
  ctaBlock        = (parsed.ctaBlock      || '').trim();
  popupData       = parsed.popupContent   || null;
} catch(e) {
  // Fallback por marcadores
  const cm = cleaned.match(/<!-- CLUSTER_BLOCK -->[\s\S]*?<!-- \/CLUSTER_BLOCK -->/);
  const tm = cleaned.match(/<!-- CTA_BLOCK -->[\s\S]*?<!-- \/CTA_BLOCK -->/);
  clusterBlock = cm ? cm[0] : '';
  ctaBlock     = tm ? tm[0] : '';
}

// --- Construir el bloque de popup con JS inline ---
// El script es una plantilla fija; solo el CONTENIDO viene de DeepSeek
let popupBlock = '';
if (postData.needsPopup && popupData && popupData.title) {
  const uid = 'pp' + postData.id.toString().slice(-8); // ID único del post
  const bgColor    = popupData.bgColor  || postData.BRAND_COLOR || '#1e3a5f';
  const emojiIcon  = popupData.emoji    || '🎯';
  const title      = (popupData.title       || '').replace(/"/g, '&quot;');
  const desc       = (popupData.description || '').replace(/"/g, '&quot;');
  const ctaText    = (popupData.ctaText     || 'Ver más').replace(/"/g, '&quot;');
  const ctaUrl     = popupData.ctaUrl       || postData.FUNNEL_URL || '#';

  popupBlock = `<!-- POPUP_BLOCK -->
<div id="${uid}-overlay" style="display:none;position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.72);z-index:2147483647;align-items:center;justify-content:center;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;">
  <div style="background:${bgColor};color:#fff;padding:36px 30px;max-width:480px;width:92%;border-radius:18px;position:relative;text-align:center;box-shadow:0 20px 60px rgba(0,0,0,0.5);animation:ppSlide 0.35s ease;">
    <style>@keyframes ppSlide{from{transform:translateY(40px);opacity:0}to{transform:translateY(0);opacity:1}}</style>
    <button onclick="document.getElementById('${uid}-overlay').style.display='none'" style="position:absolute;top:12px;right:16px;background:rgba(255,255,255,0.18);border:none;color:#fff;font-size:22px;cursor:pointer;width:34px;height:34px;border-radius:50%;display:flex;align-items:center;justify-content:center;line-height:1;">×</button>
    <div style="font-size:52px;margin:0 auto 16px;">${emojiIcon}</div>
    <h3 style="margin:0 0 14px;font-size:1.4em;font-weight:800;color:#fff;line-height:1.3;">${title}</h3>
    <p style="margin:0 0 24px;font-size:0.97em;opacity:0.9;line-height:1.6;">${desc}</p>
    <a href="${ctaUrl}" rel="noopener" style="display:inline-block;background:#fff;color:${bgColor};padding:14px 36px;border-radius:50px;font-weight:800;font-size:1.05em;text-decoration:none;box-shadow:0 4px 20px rgba(0,0,0,0.25);">${ctaText}</a>
    <p onclick="document.getElementById('${uid}-overlay').style.display='none'" style="margin:16px 0 0;font-size:0.8em;opacity:0.55;cursor:pointer;">No gracias, lo veré después</p>
  </div>
</div>
<script>
(function(){
  var shown=false;
  var uid='${uid}';
  var startT=Date.now();
  function show(){if(shown)return;shown=true;document.getElementById(uid+'-overlay').style.display='flex';}
  // Scroll 40%
  window.addEventListener('scroll',function(){
    var d=document.documentElement;
    var pct=d.scrollTop/(d.scrollHeight-d.clientHeight)*100;
    if(pct>=40)show();
  },{passive:true});
  // Exit intent
  document.addEventListener('mouseleave',function(e){
    if(e.clientY<0&&Date.now()-startT>5000)show();
  });
  // Popup universal a los 10s
  setTimeout(function(){show();},10000);
})();
<\/script>
<!-- /POPUP_BLOCK -->`;
}

// --- Inserción segura (Ley 1) ---
function appendSafe(html, content, marker, position) {
  if (!html || !html.includes(marker)) return content;
  if (content.includes(marker)) return content; // ya existe → no tocar
  if (position === 'end') return content + '\n' + html;
  const cut = Math.floor(content.length * 0.65);
  const anchor = content.lastIndexOf('</p>', cut);
  const at = anchor > 0 ? anchor + 4 : cut;
  return content.slice(0, at) + '\n' + html + '\n' + content.slice(at);
}

let content = postData.content;
if (postData.needsCluster && clusterBlock) content = appendSafe(clusterBlock, content, '<!-- CLUSTER_BLOCK -->', 'middle');
if (postData.needsCTA     && ctaBlock)     content = appendSafe(ctaBlock,     content, '<!-- CTA_BLOCK -->',     'end');
if (postData.needsPopup   && popupBlock)   content = appendSafe(popupBlock,   content, '<!-- POPUP_BLOCK -->',   'end');

const changed = content !== postData.content;

return {
  json: {
    id:          postData.id,
    title:       postData.title,
    BLOG_ID:     postData.BLOG_ID,
    newContent:  content,
    _noChange:   !changed,
    addedBlocks: [
      postData.needsCluster && clusterBlock ? 'cluster' : null,
      postData.needsCTA     && ctaBlock     ? 'cta'     : null,
      postData.needsPopup   && popupBlock   ? 'popup'   : null
    ].filter(Boolean),
    _sheetRowNumber: postData._sheetRowNumber,
    SHEET_ID:        postData.SHEET_ID,
    HOJA_BLOGS:      postData.HOJA_BLOGS,
    BLOG_NAME:       postData.BLOG_NAME,
    ESTRATEGIA:      postData.ESTRATEGIA
  }
};

const blogData = $('🎯 Seleccionar Blog (Rotación Autopilot)').first().json;
return [{
  json: {
    status:      '✅ Blog Factory Autopilot — ciclo completado',
    blog:        blogData.BLOG_NAME,
    estrategia:  blogData.ESTRATEGIA,
    timestamp:   new Date().toLocaleString('es-MX', { timeZone: 'America/Mexico_City' }),
    leyes:       '⚖️ Ley 1 (sin modificar contenido) + Ley 2 (sin duplicar) activas',
    proximoCiclo: 'El próximo día se procesará el siguiente blog en la rotación automática.'
  }
}];
